import * as peg from '../../cql/parser.min.js'
import * as fluent from './fluent.js'
export { fluent }

export const ttl = (rule, x,...args) => {
  const src = String.raw (x,...'?'.repeat(args.length))
  return peg.parse (src, { startRule: rule, args })
}

export const ttl_ = (rule, ffn) => (x,...args) => {
  if (x?.raw) return ttl (rule, x,...args)
  else return ffn (x,...args)
}

export const val      = ttl_('val',     fluent.val)
export const ref      = ttl_('ref',     fluent.ref)
export const expr     = ttl_('expr',    fluent.expr)
export const subject  = ttl_('subject', fluent.subject)
export const columns  = ttl_('columns', fluent.columns)
export const values   = ttl_('values',  fluent.values)
export const where    = ttl_('where',   fluent.where)
export const having   = ttl_('having',  fluent.having)
export const groupBy  = ttl_('groupBy', fluent.groupBy)
export const orderBy  = ttl_('orderBy', fluent.orderBy)
